// The upgrade re-validates the detected command against a freshly-scaffolded
// project; a first compile (cargo/go/cmake) can be slow, so allow generous time.
private static readonly TimeSpan UpgradeValidationTimeout = TimeSpan.FromSeconds(120);

/// <summary>
/// Validation timeout for the GUI "Create config" path. A first-ever run may
/// cold-compile the whole package (measured ~2 min for a small SwiftPM package);
/// this budget tolerates cold toolchain compiles. Once a config exists the task
/// pipeline uses testTimeoutMs, so this only affects the manual create-config path.
/// </summary>
public static readonly TimeSpan CreateConfigValidationTimeout = TimeSpan.FromMinutes(2);

/// <summary>
/// Default validation timeout during init (60 s). Real suites can take ~30 s;
/// this gives headroom without being unbounded. Once a config exists the
/// task pipeline uses testTimeoutMs, so this only affects the create-config path.
/// </summary>
private static readonly TimeSpan InitValidationTimeout = TimeSpan.FromSeconds(60);

// Injectable so tests can supply a fake completer; defaults to the frontier proxy.
public LlmTestCommandFinder TestCommandFinder { get; init; } = new();

/// <summary>
/// Injectable factory for the test runner used during create-config validation.
/// Receives the <see cref="ProjectBootstrapper.CreateConfigValidationTimeout"/>
/// (2 min). When null, <c>CreateConfigAsync</c> falls back to a new
/// <see cref="DirectExecTestRunner"/> with that timeout — production behaviour
/// unchanged. Tests inject a lambda that records the <see cref="TimeSpan"/> and
/// returns an instant fake <see cref="ITestRunner"/> (no real processes).
/// </summary>
public Func<TimeSpan, ITestRunner>? InitValidationRunnerFactory { get; set; }

